import { Modal } from 'react-native'
import { UpgradePlanScreen } from './UpgradePlanScreen'
import { useEffect, useState } from 'react'
import { upgradePlanEmitter, UpgradePlanEvents } from '@/utils/emitter'
import { colors, useTheme } from '@/theme'
import { usePurchase } from '@/utils/hooks'

export function UpgradePlanModal() {
	const [isVisible, setIsVisible] = useState(false)

	useEffect(() => {
		const handleOpenModal = () => {
			setIsVisible(true)
		}
		upgradePlanEmitter.on(UpgradePlanEvents.OPEN_MODAL, handleOpenModal)
		return () => {
			upgradePlanEmitter.off(UpgradePlanEvents.OPEN_MODAL, handleOpenModal)
		}
	}, [])
	const { theme } = useTheme()

	const { isPurchasing, purchase } = usePurchase({
		onSuccess: () => {
			setIsVisible(false)
		}
	})

	return (
		<Modal
			visible={isVisible}
			onRequestClose={() => setIsVisible(false)}
			animationType="slide"
			allowSwipeDismissal={!isPurchasing}
			presentationStyle="formSheet"
			statusBarTranslucent
			backdropColor={colors[theme].gray[25]}
		>
			<UpgradePlanScreen onPurchase={purchase} isPurchasing={isPurchasing} />
		</Modal>
	)
}
